INSERT INTO public.products (name, description, price, category, image_url, features, stock, slug, sku, brand, gallery, specs, hidden) VALUES
('Ventilator axial de tubulatură STORM 350, Debit 2600mc/h, Carcasă metalică, Diametru Ø350mm', $ev$Ventilatoare axiale de joasă presiune în carcasă de oțel acoperită cu polimer negru. Proiectat pentru sistemele de ventilație de alimentare și evacuare și pentru răcirea unităților de compresie-condens. Funcționează în modul de alimentare sau de evacuare, în funcție de modul în care este montat în sistemul de ventilație. Motoarele cu rulmenți cu bile de inducție sunt protejate împotriva supraîncălzirii. STORM poate fi echipat cu un motor cu inducție bipolar sau cvadrupolar. Configurația depinde de dimensiunea ventilatorului. Modelele cu diametrul de 200, 250, 300 mm sunt echipate cu motor bipolar. Modelele cu diametrul de 350, 400, 450 mm sunt echipate cu un motor cvadrupol. Montat pe suprafețele de perete și tavan cu panou special de montaj pătrat (flanșă). Echipat cu o flanșă pentru montare ușoară în conducte de aer de dimensiunea corespunzătoare. Grad de protecție IPX4 la pătrunderea echipamentelor electrice.$ev$, 0, 'Ventilatoare Axiale și Centrifugale', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/S350-1-ecovent_4a1b639b-a7f7-4499-987b-f782789f9dbf.webp?v=1750943586', '[]'::jsonb, 0, 'ventilator-axial-de-tubulatura-storm-350-debit-2600mc-h-carcasa-metalica', 'Storm350', 'Era Pro', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/S350-2.webp?v=1750943586', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/3storm200_d9126945-efca-447b-8184-68c96bde763a.webp?v=1750943586', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/4STORM250_8b462af5-25f8-4886-a059-ef3e6ab2efb6.webp?v=1750943586', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/6storm200_575e3727-405c-493f-9e1a-f050c0c1c627.webp?v=1750943586']::text[], '{}'::jsonb, true),
('Ventilator axial de tubulatură STORM 300, Debit 2300 mc/h, Carcasă metalică, Diametru Ø300mm', $ev$Ventilatoare axiale de joasă presiune în carcasă de oțel acoperită cu polimer negru. Proiectat pentru sistemele de ventilație de alimentare și evacuare și pentru răcirea unităților de compresie-condens. Funcționează în modul de alimentare sau de evacuare, în funcție de modul în care este montat în sistemul de ventilație. Motoarele cu rulmenți cu bile de inducție sunt protejate împotriva supraîncălzirii. STORM poate fi echipat cu un motor cu inducție bipolar sau cvadrupolar. Configurația depinde de dimensiunea ventilatorului. Modelele cu diametrul de 200, 250, 300 mm sunt echipate cu motor bipolar. Modelele cu diametrul de 350, 400, 450 mm sunt echipate cu un motor cvadrupol. Montat pe suprafețele de perete și tavan cu panou special de montaj pătrat (flanșă). Echipat cu o flanșă pentru montare ușoară în conducte de aer de dimensiunea corespunzătoare. Grad de protecție IPX4 la pătrunderea echipamentelor electrice.$ev$, 0, 'Ventilatoare Axiale și Centrifugale', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/S350-1-ecovent.webp?v=1750943565', '[]'::jsonb, 0, 'ventilator-axial-de-tubulatura-storm-300-debit-2300-mc-h-carcasa-metalica', 'Storm300', 'Era Pro', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/2storm200.webp?v=1750943565', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/3storm200_e2493ab2-2963-4125-b383-66f24729c664.webp?v=1750943565', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/5storm200_e9ec1e7c-cef1-4f14-9bc6-f8635040155c.webp?v=1750943565', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/6storm200_e655e8ac-460b-4b12-b397-c37b994258dc.webp?v=1750943565']::text[], '{}'::jsonb, true),
('Ventilator axial de tubulatură STORM 200, Debit 890 mc/h, Carcasă metalică, Diametru Ø200mm', $ev$Ventilatoare axiale de joasă presiune în carcasă de oțel acoperită cu polimer negru. Proiectat pentru sistemele de ventilație de alimentare și evacuare și pentru răcirea unităților de compresie-condens. Funcționează în modul de alimentare sau de evacuare, în funcție de modul în care este montat în sistemul de ventilație. Motoarele cu rulmenți cu bile de inducție sunt protejate împotriva supraîncălzirii. STORM poate fi echipat cu un motor cu inducție bipolar sau cvadrupolar. Configurația depinde de dimensiunea ventilatorului. Modelele cu diametrul de 200, 250, 300 mm sunt echipate cu motor bipolar. Modelele cu diametrul de 350, 400, 450 mm sunt echipate cu un motor cvadrupol. Montat pe suprafețele de perete și tavan cu panou special de montaj pătrat (flanșă). Echipat cu o flanșă pentru montare ușoară în conducte de aer de dimensiunea corespunzătoare. Grad de protecție IPX4 la pătrunderea echipamentelor electrice.$ev$, 0, 'Ventilatoare Axiale și Centrifugale', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/2STORM250.jpg?v=1774507732', '[]'::jsonb, 0, 'ventilator-axial-de-tubulatura-storm-200-debit-890-mc-h-carcasa-metalica', 'Storm200', 'Era Pro', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/3storm200.jpg?v=1774507731', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/1storm-200.jpg?v=1774507731', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/5storm200.jpg?v=1774507732', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/6storm200.jpg?v=1774507731']::text[], '{}'::jsonb, true),
('Ventilator centrifugal MARS 150, Debit 550 mc/h, Carcasă metalică, Diametru Ø150mm', $ev$Ventilatoare centrifugale cu carcasă din oțel galvanizat. Proiectat pentru sistemele de ventilație de alimentare și evacuare. Cutie terminală rezistentă la apă. Funcționează în modul de alimentare sau de evacuare, în funcție de modul în care este montat în sistemul de ventilație. Proiectat pentru montare în linie în conductele cu diametrul corespunzător. Poate fi instalat în orice punct al sistemului de ventilație și în orice unghi. Echipat cu un motor monofazat cu rotor extern cu rulment de bile și un rotor centrifugal cu palete curbate. Beneficiaza de protecție la supraîncălzire cu repornire automată. Montat pe suprafețele de perete și tavan cu suporturi speciale de prindere. MARS GDF 200 / 250 / 315 sunt echipate cu lame de otel. Gradul de protecție la pătrunderea echipamentelor electrice este IPX4, pentru motor - IP44.$ev$, 0, 'Ventilatoare Axiale și Centrifugale', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/1mars100_5a753786-4c46-4292-9289-07eed6c8634a.webp?v=1750943438', '[]'::jsonb, 0, 'ventilator-centrifugal-mars-150-debit-550-mc-h-carcasa-metalica-diametru-o150mm', 'MARSGDF150', 'Ecovent', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/2mars100_cfc108aa-583d-46e2-8092-15b195a385bb.webp?v=1750943438', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/111_1ab3222a-088c-454b-aa28-e02ddd43771e.webp?v=1750943438']::text[], '{}'::jsonb, true),
('Set filtre Dantherm G4+F7 pentru centrală HCV400 și HCV460', $ev$Set filtre Dantherm G4+F7 pentru centrală HCV400 și HCV460

Setul de filtre Dantherm este compatibil cu centralele de ventilație HCV400 și HCV460. Pachetul conține două filtre individuale: un filtru G4 și un filtru F7.

Detalii și documentație

Set de filtre (2 filtre simple într-o cutie, filtru G4 și filtru F7).

Manual utilizare

Ghiduri și informații utile

Momentan acest produs nu are un manual de utilizare pe care să-l descarci. Pentru informații suplimentare te rugăm să ne contactezi.$ev$, 0, 'Filtre Centrale de Ventilație', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/098346_1.jpg?v=1750943106', '[]'::jsonb, 0, 'set-filtre-dantherm-g4-f7-pentru-centrala-hcv400-si-hcv460', '098346', 'Dantherm', ARRAY[]::text[], '{}'::jsonb, true),
('Recuperator de căldură Helty Flow Plus, Dublu Flux, Senzor Umiditate, Randament 91%, Filtru F7+G4', $ev$Sistem compact, silențios și de înaltă performanță cu două găuri. Ușurință garantată în instalare și integrarea optimă în orice mediu. Menține umiditatea sub control și ajustează automat ventilația pentru un confort sporit, fără pierderi de energie.

Controlul umidității și a condensului

Cu FlowPLUS aerul din casă este întotdeauna proaspăt, plăcut și purificat. Echipat standard cu un senzor higrometric , acest recuperator de căldură măsoară nivelul de umiditate din aer și ajustează automat funcționarea după caz. Condițiile climatice ideale sunt menținute în mediul în care vă petreceți timpul, evitând formarea condensului și mucegaiului.‎

În plus, testat la TÜV SÜD în conformitate cu standardul EN 13141-8, înseamnă că sistemul poate recupera până la 91% din căldura din aerul extras și poate transfera această căldură în aerul care intră în înapoi în încăpere.

Confort și economie, chiar și vara

Temperatura interioară rămâne neschimbată, ceea ce înseamnă că nu vor exista pierderi asociate ferestrelor deschise, ceea ce înseamnă economii la factura de energie.

Funcția electronică de free cooling (activată de utilizator) înseamnă că sistemul de ventilație FlowPLUS oferă, de asemenea, o contribuție cu cost zero la aerul condiționat interior atunci când condițiile de temperatură exterioară sunt mai confortabile.

De exemplu, în serile de vară când aerul exterior este mai rece și mai plăcut decât aerul din interior, recuperatorul de căldură poate fi folosit pentru a furniza aer natural proaspăt și purificat în spațiile interioare.

Ușor de instalat, ușor de utilizat

Montat pe perete în mai puțin de o oră , FlowPLUS poate fi instalat ușor și rapid în orice mediu rezidențial, mai ales atunci când clădirile sunt locuite sau renovate.

Pe lângă panoul de funcții și telecomanda cu infraroșu, sistemul de ventilație poate fi gestionat și prin smartphone sau tabletă prin aplicația Air Guard .

Aplicația, dezvoltată de Helty, conectează fiecare unitate la rețeaua Wi-Fi , permițându-vă să reglați funcționarea recuperatorului de căldură și să monitorizați valorile temperaturii și umidității în încăpere.‎

Aplicația poate controla unitatea doar în rețeaua WI-FI locală la care este conectată unitatea de ventilație. Dacă se dorește control prin aplicație de la distanță este necesară achiziționarea și instalarea unui panou de control cu funcție cloud.

Singura grijă a utilizatorului este să schimbe filtrul atunci când indicatorul LED se aprinde.

Manual utilizare

Ghid instalare și informații utile

Ghid Instalare Helty Flow Plus

Manual de utilizare Helty Flow Plus (EN)$ev$, 0, 'Recuperatoare de Căldură', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ecovent_Recuperator_HeltyFlowPlus-Elite.jpg?v=1750942822', '[]'::jsonb, 0, 'recuperator-de-caldura-helty-flow-plus', '1VMC01019A', 'Helty', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ecovent_Recuperator_HeltyFlowPlus-Elite2_7b88b003-0bf3-4842-a5d6-84f5ba540957.jpg?v=1750942822', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Healty-Flow-Plus-2.jpg?v=1750942822']::text[], '{}'::jsonb, true),
('Clapetă antiretur pRim, pRestige, pRemium, aRid, aRc - Ø150mm', $ev$Clapetă antiretur pRim, pRestige, pRemium, aRid, aRc - Ø150mm

Clapeta antiretur Ø150 mm este destinată gamelor pRim, pRestige, pRemium, aRid și aRc. Fabricată din ABS, contribuie la limitarea pătrunderii mirosurilor prin orificiul de ventilație.

Detalii și documentație

Ofera protectie impotriva tuturor mirosurilor care pot intra in incapere prin orificiile de ventilatie. Materialul din care sunt construite (ABS) a sporit durabilitatea produsului, lucru important datorita deschiderii si inchiderii constante a clapetei de retur in timpul functionarii ventilatorului.$ev$, 0, 'Accesorii Ventilație', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Clapeta-antiretur-pentru-seria-de-ventilatoare-pRim_e5b0a65a-1de6-4211-8451-5fcb0d88dbed.jpg?v=1750941476', '[]'::jsonb, 0, 'clapeta-antiretur-prim-prestige-premium-arid-arc-o150mm', 'CLA150', 'airRoxy', ARRAY[]::text[], '{}'::jsonb, true),
('Ventilator centrifugal de tubulatură CYCLONE 250, Debit 1100mc/h, Diametru Ø250mm', $ev$CARACTERISTICI GENERALE VENTILATOR CENTRIFUGAL

Tip produs: Ventilator centrifugal

Functii: Protectie la supraincalzire, Pornire automata, Monofazic

Motor protejat la supraincalzire. Oferă o siguranță sporită în utilizare.

Motor pe rulemnti (asigura pana la 40000 ore de functionare).

Descrierea ventilator centrifugal:

• Ventilator centrifugal pentru tubulatura.

• Proiectat pentru admisia si evacuara aerului in sisteme de ventilatie.

• Corpul ventilatorului este confectionat din masa plastica rezistenta de cea mai buna calitate.

• Corpul ventilatorului este ermetic izolat.

• Motor monofazic, cu rotor extern si echipat cu roata centrifugala cu palete curbate, cu protectie termica incorporata si pornire automata.

• Proiectat pentru montarea pe canalele cu diametru adecvat in orice punct al sistemului si sub orice unghi.

• Fixarea pe perete sau tavan se realizeaza cu ajutorul unor coliere de fixare.

• Viteza de functionare poate fi reglata de la viteza minima la viteza maxima cu ajutorul unui variator de debit sau cu un regulator de tensiune.

• Pot fi conectate mai multe ventilatoare la un singur regulator cunconditia ca consumul total de energie sa nu depaseasca valoarea maxima admisa de regulator

• Gradul de protecție a echipamentului electric de penetrarea obiectelor solide și a apei - IP24, motor - IP44.$ev$, 0, 'Ventilatoare Axiale și Centrifugale', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/CYCLONE-EBM-100_a131ac37-3e54-4d24-8a3c-ed185bd5266b.jpg?v=1750939938', '["Ventilator centrifugal pentru tubulatura.","Proiectat pentru admisia si evacuara aerului in sisteme de ventilatie.","Corpul ventilatorului este confectionat din masa plastica rezistenta de cea mai buna calitate.","Corpul ventilatorului este ermetic izolat.","Motor monofazic, cu rotor extern si echipat cu roata centrifugala cu palete curbate, cu protectie termica incorporata si pornire automata.","Proiectat pentru montarea pe canalele cu diametru adecvat in orice punct al sistemului si sub orice unghi.","Fixarea pe perete sau tavan se realizeaza cu ajutorul unor coliere de fixare.","Gradul de protecție a echipamentului electric de penetrarea obiectelor solide și a apei - IP24, motor - IP44."]'::jsonb, 0, 'ventilator-centrifugal-de-tubulatura-cyclone-250', 'CYCLONE250', 'Ecovent', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/CYCLONE-EBM_5be41063-a6fc-4592-b2b7-497dbe60178c.png?v=1750939938']::text[], '{}'::jsonb, true),
('Cot Tubulatură Ø100mm, 90° PVC', $ev$Cot Tubulatură Ø100mm, 90° PVC

Cotul din PVC Ø100 mm conectează tubulaturi circulare la un unghi de 90°. Este destinat schimbării direcției traseului, cu montare directă pe tuburi de același diametru.

Detalii și documentație

• Cot utilizat pentru conectarea tubulaturilor de același diametru la un unghi de 90 °.

• Poate fi utilizat pentru conectarea directa cu tuburile circulare

• Fabricat din plastic PVC de inalta calitate

• Diametru: 100mm$ev$, 0, 'Accesorii Ventilație', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Cot-O100-mm-90_C2_B0-PVC.jpg?v=1750938556', '["Cot utilizat pentru conectarea tubulaturilor de același diametru la un unghi de 90 °.","Poate fi utilizat pentru conectarea directa cu tuburile circulare","Fabricat din plastic PVC de inalta calitate","Diametru: 100mm"]'::jsonb, 0, 'cot-tubulatura-100mm-90-pvc', '10KKP', 'Ecovent', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/cot-90-cu-tub_1a896eff-9569-4c21-9878-1de64ad8b3c7.png?v=1750938556', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/cot-90-cu-grila_41d004ba-5872-444f-8353-9f319d9f0c25.png?v=1750938556', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/D0_9A_D0_9A_D0_9F_041635a8-622b-4075-b3f8-12005ff5cd44.png?v=1750938556']::text[], '{}'::jsonb, true),
('TYPHOON 100 2SP - Ventilator axial de tubulatură TYPHOON 100 2SP, Debit 220mc/h, 2 Trepte de viteze, Diametru Ø100mm', $ev$Noua serie de ventilatoare TYPHOON este menită să creeze condiții confortabile în camere în care este necesară circulația aerului și umiditate constantă.

O caracteristică distinctivă a acestei serii sunt piesele individuale din plastic ABS, care permit echipamentelor să nu sufere de coroziune, sunt ușor de instalat și nivelul de zgomot este redus.

Ventilatorul are motoare moderne cu două moduri de mare viteză.$ev$, 0, 'Ventilatoare Axiale și Centrifugale', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ventilator-Era-Pro-100-Typhoon-2SP-3.jpg?v=1750937708', '[]'::jsonb, 0, 'typhoon-100-2sp', 'TYPHOON1002SP', 'Ecovent', ARRAY['https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ventilator-Era-Pro-100-Typhoon-2SP-6.jpg?v=1750937708', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ventilator-Era-Pro-100-Typhoon-2SP-5.jpg?v=1750937709', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ventilator-Era-Pro-100-Typhoon-2SP-4.jpg?v=1750937708', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ventilator-Era-Pro-100-Typhoon-2SP-2.jpg?v=1750937708', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Ventilator-Era-Pro-100-Typhoon-2SP.jpg?v=1750937708', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Screenshot_2.jpg?v=1750937708', 'https://cdn.shopify.com/s/files/1/0951/0941/5241/files/Screenshot_3.jpg?v=1750937709']::text[], '{}'::jsonb, true),
('Filtru rezervă pentru purificator de aer LEVOIT Vital 100, 3-in-1, Pre-filtru lavabil, Filtru HEPA și Filtru de carbon activ cu eficiență ridicată, Vital 100-RF', $ev$● EFICIENTA RIDICATA PENTRU CAMERE MARI

Filtrul de aer 3 în 1 pentru Vital 100 permite purificatorului sa elimine eficient poluantii din aer prin combinatia echilibrata dintre filtrul preliminar fin, filtrul True HEPA si filtrul de Carbon Activ. Acest filtru de aer capteaza 99,97% din toti poluantii existenti in aer de până la 0,3 microni, cum ar fi polenul, praful, parul de la animale de companie, bacterii*, virusuri*, fumul de tutun si alte mirosuri casnice.

● USOR DE INTRETINUT

Filtrul pentru purificatorul de aer Levoit Vital 100 are un prefiltru de nylon, care retine particulele mari din componenta aerului si care, de asemenea, poate fi curatat. Recomandarea noastra este sa curatati acest filtru cu aspiratorul o data pe luna pentru ca purificatorul sa isi mentina performantele si sa prelungiti durata de viata a filtrului.

● 100% FARA OZON

Purificatoarele de aer Levoit evita sa foloseasca lumina UV / Ion. O metoda de curatare a aerului pe care cercetarile au dovedit ca poate produce ozon daunator sanatatii utilizatorilor. In schimb folosesc filtre performante ultra-fine care au grija ca tu sa respiri un aer curat si sanatos.

● SIGUR SI CERTIFICAT

Filtrul original Levoit este sigur pentru sanatatea ta! Acesta este verificat de AHAM, care este autoritatea de evaluare a purificatoarelor de aer. De asemenea, este verificat Energy Star, CARB, certificat FCC, listat ETL si certificat CA Prop 65.

Nota: Recomandam schimbarea filtrului odata la 6-8 luni.

*Bacteriile si virusurile sunt retinute de filtru, dar nu eliminate.

